DELIMITER ;;
CREATE DEFINER=`yazmin.esquivel`@`%` FUNCTION `fn_fecha_nacimiento_prueba`(
    p_edad_min INT,
    p_edad_max INT,
    p_num INT
) RETURNS date
    NO SQL
BEGIN
    DECLARE v_edad INT;
    DECLARE v_fecha DATE;

    SET v_edad = p_edad_min +
        MOD(p_num, p_edad_max - p_edad_min + 1);

    SET v_fecha = DATE_SUB(
        CURDATE(),
        INTERVAL v_edad YEAR
    );

    RETURN v_fecha;
END ;;
DELIMITER ;
